function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listT03Invoices(
  query: Record<string, string | number | boolean>,
): Promise<T03InvoiceListItem[]> {
  const res = await apiClient.get<BffResponse<T03InvoiceListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getT03Invoice(sttRec: string): Promise<T03Invoice> {
  const res = await apiClient.get<BffResponse<T03Invoice>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createT03Invoice(body: T03InvoiceWrite): Promise<T03Invoice> {
  const res = await apiClient.post<BffResponse<T03Invoice>>(BASE, body);
  return unwrap(res);
}

export async function updateT03Invoice(sttRec: string, body: T03InvoiceWrite): Promise<T03Invoice> {
  const res = await apiClient.put<BffResponse<T03Invoice>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
